begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
 ('11111111-1111-4111-8111-111111111111','solver@example.com',now()),
 ('22222222-2222-4222-8222-222222222222','other@example.com',now()),
 ('33333333-3333-4333-8333-333333333333','abid.ibn.ashraf@gmail.com',now());
insert into public.profiles(id,username) values('11111111-1111-4111-8111-111111111111','Solver'),('22222222-2222-4222-8222-222222222222','Other'),('33333333-3333-4333-8333-333333333333','Owner');
create temp table results(name text primary key,result jsonb);
grant all on results to authenticated,anon;
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
insert into results values('first',public.record_online_attempt(public.begin_attempt('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),'{"format":"fto-replay-v1","size":3,"complete":true,"solveMs":100,"events":[]}'));
select is((select jsonb_array_length(result->'candidates') from results where name='first'),1,'An eligible PB returns an explicit single candidate');
select is((select result->'submitted' from results where name='first'),'[]'::jsonb,'Recording a PB submits nothing');
select is(jsonb_array_length(public.my_leaderboard_candidates()),1,'Owner can retrieve an unsubmitted PB after reload');
set local role postgres;
select is((select count(*)::int from public.submissions where status='pending'),0,'Review queue stays empty before the user clicks Submit');
set local role authenticated;
insert into results values('legacy',public.finish_attempt(public.begin_attempt('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),'{"format":"fto-replay-v1","size":3,"complete":true,"solveMs":90,"events":[]}'));
select throws_ok($$select public.submit_leaderboard((select (result->'candidates'->0->>'id')::uuid from results where name='first'))$$,'P0001','This PB has been replaced or is unavailable','An improved PB supersedes the older unsubmitted candidate');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
select is(public.my_leaderboard_candidates(),'[]'::jsonb,'Another account cannot see private PB candidates');
select throws_ok($$select public.submit_leaderboard((select (result->'candidates'->0->>'id')::uuid from results where name='legacy'))$$,'P0001','This PB has been replaced or is unavailable','Another account cannot submit this PB');
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',true);
select is(public.review_queue(),'[]'::jsonb,'Even the legacy finish API no longer auto-submits');
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select is(public.submit_leaderboard((select (result->'candidates'->0->>'id')::uuid from results where name='legacy'))->>'status','pending','Explicit submit enters pending review');
select is(public.submit_leaderboard((select (result->'candidates'->0->>'id')::uuid from results where name='legacy'))->>'status','pending','Repeated clicks are idempotent');
set local role postgres;
select is((select count(*)::int from public.submissions where status='pending'),1,'Repeated clicks keep one submission row');
set local role authenticated;
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',true);
select is(jsonb_array_length(public.review_queue()),1,'Admin sees the explicitly submitted result');
select lives_ok($$select public.review_submission((select (result->'candidates'->0->>'id')::uuid from results where name='legacy'),true,'Reviewed')$$,'Admin approves a manually submitted PB');
set local role anon;
select is((select count(*)::int from public.leaderboard('single')),1,'Approved explicit submission becomes public');
select throws_ok($$select public.my_leaderboard_candidates()$$,'42501',null,'Anonymous clients cannot read candidate records');
select throws_ok($$select public.submit_leaderboard('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')$$,'42501',null,'Anonymous clients cannot submit PBs');
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
insert into results values('undo',public.record_online_attempt(public.begin_attempt('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'),'{"format":"fto-replay-v1","size":3,"complete":true,"solveMs":10,"usedUndo":true,"events":[]}'));
select is((select (result->>'invalid_pb')::boolean from results where name='undo'),true,'A PB with undo is explicitly identified as invalid');
select is((select jsonb_array_length(result->'candidates') from results where name='undo'),0,'Undo PB cannot create a single submission candidate');
select public.record_online_attempt(public.begin_attempt('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'),jsonb_build_object('format','fto-replay-v1','size',3,'complete',true,'solveMs',100+n*10,'events','[]'::jsonb)) from generate_series(0,3) n;
insert into results values('ao5',(select e from jsonb_array_elements(public.my_leaderboard_candidates()) e where e->>'metric'='ao5'));
select is((select (result->>'ms')::double precision from results where name='ao5'),120::double precision,'Undo still counts as a trimmed DNF in the online ao5');
select lives_ok($$select public.submit_leaderboard((select (result->>'id')::uuid from results where name='ao5'))$$,'The solver can choose to submit the valid ao5 separately');
insert into results values('faster',public.record_online_attempt(public.begin_attempt('cccccccc-cccc-4ccc-8ccc-cccccccccccc'),'{"format":"fto-replay-v1","size":3,"complete":true,"solveMs":80,"events":[]}'));
select is(jsonb_array_length(public.my_leaderboard_candidates()),1,'A new faster single remains a private choice');
set local role postgres;
update public.submissions set created_at=now()-interval '31 days' where status='draft';
select public.prune_recordings();
select is((select bool_and(evidence_refs is null) from public.submissions where status='draft'),true,'Expired drafts release replay evidence');
set local role authenticated;
select is(public.my_leaderboard_candidates(),'[]'::jsonb,'Expired recordings are not offered for submission');
select throws_ok($$select public.submit_leaderboard((select (result->'candidates'->0->>'id')::uuid from results where name='faster'))$$,'P0001','This PB recording has expired','Expired drafts cannot be submitted');
select is(jsonb_array_length(public.record_online_attempt(public.begin_attempt('cccccccc-cccc-4ccc-8ccc-cccccccccccc'),'{"format":"fto-replay-v1","size":3,"complete":true,"solveMs":85,"events":[]}'::jsonb)->'candidates'),1,'An unsubmitted faster result does not block beating the approved leaderboard result');
insert into results values('offer85',(select e from jsonb_array_elements(public.my_leaderboard_candidates()) e where e->>'metric'='single'));
select is((select (result->>'leaderboard_ms')::double precision from results where name='offer85'),90::double precision,'Offer compares with the approved leaderboard result');
select public.submit_leaderboard((select (result->>'id')::uuid from results where name='offer85'));
insert into results values('new88',public.record_online_attempt(public.begin_attempt('cccccccc-cccc-4ccc-8ccc-cccccccccccc'),'{"format":"fto-replay-v1","size":3,"complete":true,"solveMs":88,"events":[]}'));
select is((select (result->'candidates'->0->>'pending_ms')::double precision from results where name='new88'),85::double precision,'Offer exposes the pending result that will be replaced');
select public.submit_leaderboard((select (result->'candidates'->0->>'id')::uuid from results where name='new88'));
set local role postgres;
select is((select count(*)::integer from public.submissions where user_id='11111111-1111-4111-8111-111111111111' and metric='single' and status='pending'),1,'Only the latest explicitly submitted single stays pending');
select is((select ms from public.submissions where metric='single' and status='pending'),88::double precision,'A newer eligible submission replaces the pending result even if slower');
select is((select count(*)::integer from public.submissions where metric='ao5' and status='pending'),1,'Replacing a single does not remove the pending ao5');
set local role authenticated;
insert into results values('stale89',public.record_online_attempt(public.begin_attempt('cccccccc-cccc-4ccc-8ccc-cccccccccccc'),'{"format":"fto-replay-v1","size":3,"complete":true,"solveMs":89,"events":[]}'));
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',true);
select public.review_submission((select (result->'candidates'->0->>'id')::uuid from results where name='new88'),true,'Approved newer single');
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select is(public.my_leaderboard_candidates(),'[]'::jsonb,'Offers disappear if approval makes the leaderboard result faster');
select throws_ok($$select public.submit_leaderboard((select (result->'candidates'->0->>'id')::uuid from results where name='stale89'))$$,'P0001','Your leaderboard result is already equal or faster','Submission rechecks the current approved result');
select * from finish();
rollback;
